using namespace cinema;
using protocol::NodeRole;

// Synthetic sensor images use the same MSB-first RGB565 bytes as esp32-camera.
static std::vector<uint8_t> solidImage(uint16_t color, size_t width = 64, size_t height = 64) {
  std::vector<uint8_t> image(width * height * 2);
  for (size_t offset = 0; offset < image.size(); offset += 2) {
    image[offset] = color >> 8;
    image[offset + 1] = color & 255;
  }
  return image;
}

// Check sensor byte order, channel expansion, bounds, uneven ownership and edge traversal.
static void testSampling() {
  stream::Config config{7, 5, 3, 5, 3};
  std::array<uint8_t, stream::MAX_STREAM_LEDS * 3 + 1> colors{};
  assert(stream::slotCount(config, NodeRole::CameraLeft) == 7);
  assert(stream::slotCount(config, NodeRole::CameraRight) == 9);
  assert(stream::owner(config, 1) == NodeRole::CameraLeft && stream::owner(config, 2) == NodeRole::CameraRight);
  assert(stream::owner(config, 10) == NodeRole::CameraRight && stream::owner(config, 11) == NodeRole::CameraLeft);
  for (NodeRole role : {NodeRole::CameraLeft, NodeRole::CameraRight}) {
    for (uint16_t pixel : {uint16_t(0xF800), uint16_t(0x07E0), uint16_t(0x001F), uint16_t(0xFFFF), uint16_t(0)}) {
      auto image = solidImage(pixel);
      const size_t size = stream::slotCount(config, role) * 3;
      colors[size] = 0xA5;
      assert(stream::sampleRgb565(config, role, image.data(), image.size(), 64, 64, colors.data(), size));
      for (size_t i = 0; i < size; i += 3) {
        assert(colors[i] == ((pixel & 0xF800) ? 255 : 0));
        assert(colors[i + 1] == ((pixel & 0x07E0) ? 255 : 0));
        assert(colors[i + 2] == ((pixel & 0x001F) ? 255 : 0));
      }
      assert(colors[size] == 0xA5);
      assert(!stream::sampleRgb565(config, role, image.data(), image.size() - 1, 64, 64, colors.data(), size));
      assert(!stream::sampleRgb565(config, role, image.data(), image.size(), 64, 64, colors.data(), size - 1));
    }
  }
  auto gradient = solidImage(0);
  for (size_t y = 0; y < 64; y++) for (size_t x = 0; x < 64; x++) {
    const uint16_t pixel = ((x / 2) << 11) | (y << 5);
    gradient[(y * 64 + x) * 2] = pixel >> 8;
    gradient[(y * 64 + x) * 2 + 1] = pixel & 255;
  }
  config = {7, 4, 2, 4, 2};
  assert(stream::sampleRgb565(config, NodeRole::CameraLeft, gradient.data(), gradient.size(), 64, 64, colors.data(), colors.size()));
  assert(colors[0] < colors[3]); // Top runs left to right in the camera's half-screen.
  assert(colors[6] > colors[9]); // Bottom runs right to left.
  assert(colors[1] < colors[7]); // Top above bottom.
  assert(colors[13] > colors[16]); // Left edge runs bottom to top.
  assert(stream::sampleRgb565(config, NodeRole::CameraRight, gradient.data(), gradient.size(), 64, 64, colors.data(), colors.size()));
  assert(colors[0] < colors[3] && colors[12] > colors[15]);
  assert(colors[7] < colors[10]); // Right edge runs top to bottom.
  config = {1, 600, 0, 0, 0};
  assert(stream::sampleRgb565(config, NodeRole::CameraRight, gradient.data(), gradient.size(), 64, 64, colors.data(), colors.size()));
  auto tiny = solidImage(0xF800, 1, 1);
  assert(stream::sampleRgb565(config, NodeRole::CameraLeft, tiny.data(), tiny.size(), 1, 1, colors.data(), colors.size()));
  assert(!stream::sampleRgb565(config, NodeRole::CameraLeft, tiny.data(), tiny.size(), SIZE_MAX, 1, colors.data(), colors.size()));
  config = {1, 0, 600, 0, 0};
  colors[1800] = 0xA5;
  assert(stream::sampleRgb565(config, NodeRole::CameraRight, tiny.data(), tiny.size(), 1, 1, colors.data(), 1800));
  assert(colors[1797] == 255 && colors[1798] == 0 && colors[1799] == 0 && colors[1800] == 0xA5);
}

// Commands are atomic snapshots; a buffered image must reference a command older than its capture.
static void testCaptureContract() {
  stream::Config config{7, 5, 3, 5, 3};
  uint8_t payload[stream::CONFIG_SIZE];
  assert(stream::encodeConfig(config, payload, sizeof(payload)));
  stream::Config decoded;
  assert(stream::decodeConfig(payload, sizeof(payload), &decoded) && config == decoded);
  payload[2] = 1;
  assert(!stream::decodeConfig(payload, sizeof(payload), &decoded));
  payload[2] = 0;
  payload[1] = 31;
  assert(!stream::decodeConfig(payload, sizeof(payload), &decoded));
  assert(stream::encodeConfig(config, payload, sizeof(payload)));
  protocol::PacketView packet;
  packet.header.type = protocol::MessageType::StreamConfigure;
  packet.header.source = NodeRole::Controller;
  packet.header.target = NodeRole::CameraLeft;
  packet.header.bootId = 42;
  packet.header.sequence = UINT32_MAX - 1;
  packet.payload = payload;
  packet.payloadSize = sizeof(payload);
  stream::CaptureRequest request;
  assert(request.accept(packet, NodeRole::CameraLeft, 1000000));
  assert(!request.accept(packet, NodeRole::CameraLeft, 1000001));
  assert(!request.accept(packet, NodeRole::CameraRight, 1000001));
  packet.header.sequence = 1; // Signed difference accepts sequence rollover.
  assert(request.accept(packet, NodeRole::CameraLeft, 1032000));
  uint32_t sequence = 0;
  assert(request.requestForCapture(1016000, 1050000, &sequence) && sequence == UINT32_MAX - 1);
  assert(request.requestForCapture(1033000, 1050000, &sequence) && sequence == 1);
  assert(!request.requestForCapture(999999, 1050000, &sequence));
  assert(!request.requestForCapture(1033000, 1032000, &sequence));
  assert(!request.requestForCapture(1033000, 1200000, &sequence));
  packet.header.bootId = 43;
  packet.header.sequence = 1;
  assert(request.accept(packet, NodeRole::CameraLeft, 1040000));
  assert(request.count == 1 && !request.requestForCapture(1039000, 1050000, &sequence));
  config.top = 6;
  assert(stream::encodeConfig(config, payload, sizeof(payload)));
  packet.header.sequence++;
  assert(request.accept(packet, NodeRole::CameraLeft, 1050000));
  assert(request.count == 1); // Geometry changes flush old capture provenance too.
  for (uint32_t i = 3; i <= 20; i++) {
    packet.header.sequence = i;
    assert(request.accept(packet, NodeRole::CameraLeft, 1060000 + (i - 3) * 10000));
  }
  assert(request.count == stream::REQUEST_HISTORY_SIZE);
  assert(request.requestForCapture(1205000, 1235000, &sequence) && sequence == 17);
  assert(!request.requestForCapture(1159999, 1235000, &sequence));
}

// Runs the real sampling and queue producer against the real SPI slave endpoint.
static void publish(camera::SpiSlaveEndpoint& endpoint, NodeRole role, uint16_t pixel, uint32_t id) {
  stream::CaptureRequest request;
  assert(endpoint.captureRequest(&request));
  stream::Frame frame;
  frame.header.captureTimeUs = esp_timer_get_time();
  assert(request.requestForCapture(frame.header.captureTimeUs, frame.header.captureTimeUs, &frame.header.pollSequence));
  frame.header.configGeneration = request.config.generation;
  frame.header.controllerBootId = request.controllerBootId;
  frame.header.frameId = id;
  frame.header.slotCount = stream::slotCount(request.config, role);
  auto image = solidImage(pixel);
  assert(stream::sampleRgb565(request.config, role, image.data(), image.size(), 64, 64, frame.colors, sizeof(frame.colors)));
  assert(endpoint.publishFrame(frame));
}

// Exchange real full-duplex slots between production camera/controller code, including
// the one-poll response delay, bad MOSI CRC, interrupted polling, reboot and config changes.
static void testEndToEnd() {
  camera::SpiSlaveEndpoint left(NodeRole::CameraLeft), right(NodeRole::CameraRight);
  assert(left.begin() && right.begin());
  wled::CinemaController controller;
  wled::CinemaConfig config;
  config.enabled = true;
  config.generation = 7;
  config.topLeds = 5; config.rightLeds = 3; config.bottomLeds = 5; config.leftLeds = 3;
  config.color.colorBoost = config.color.darkColorBoost = config.color.smoothness = config.color.blackThreshold = 0;
  bool corruptCommand = false;
  cinemaTest::exchange = [&](bool isLeft, spi_transaction_t* transaction) {
    if (corruptCommand) {
      auto bytes = const_cast<uint8_t*>(static_cast<const uint8_t*>(transaction->tx_buffer));
      bytes[spi::SLOT_HEADER_SIZE + protocol::PACKET_HEADER_SIZE] ^= 1;
      corruptCommand = false;
    }
    cinemaTest::slaveTransaction = transaction;
    (isLeft ? left : right).run();
  };
  assert(controller.applyConfig(config));
  controller.begin();
  auto poll = [&](uint32_t time) { cinemaTest::nowMillis = time; controller.service(time); };
  poll(10000);
  publish(left, NodeRole::CameraLeft, 0xFFFF, 0);
  publish(left, NodeRole::CameraLeft, 0xF800, 1);
  poll(10016);
  publish(right, NodeRole::CameraRight, 0x001F, 1);
  poll(10032); poll(10048); poll(10064); poll(10080);
  assert(controller.cameraStatus(wled::CameraSide::Left).framesReceived == 1);
  assert(controller.cameraStatus(wled::CameraSide::Left).lastFrameId == 1); // Latest frame replaces the queued white frame.
  assert(controller.cameraStatus(wled::CameraSide::Right).framesReceived == 1);
  Segment segment;
  segment.length = 16;
  assert(controller.render(segment));
  for (uint16_t slot = 0; slot < 16; slot++) {
    assert(segment.pixels[slot] == (stream::owner(config.streamConfig(), slot) == NodeRole::CameraLeft ? 0xFF0000 : 0x0000FF));
  }
  // A lost MOSI command must leave the last coherent config available, then recover next poll.
  stream::CaptureRequest request;
  assert(left.captureRequest(&request));
  const uint32_t previous = request.lastSequence;
  corruptCommand = true;
  publish(left, NodeRole::CameraLeft, 0x07E0, 2);
  poll(10096);
  assert(left.captureRequest(&request) && request.lastSequence == previous);
  // The pending RGB slot survives in the slave while the master stops polling. Reject it.
  poll(10550); poll(10566);
  assert(controller.cameraStatus(wled::CameraSide::Left).framesReceived == 1);
  assert(controller.isCameraConnected(wled::CameraSide::Left, millis()));
  controller.render(segment);
  for (uint16_t slot = 0; slot < 16; slot++) assert(segment.pixels[slot] == 0);
  publish(left, NodeRole::CameraLeft, 0x07E0, 3);
  poll(10582); poll(10598); poll(10614); poll(10630);
  assert(controller.cameraStatus(wled::CameraSide::Left).lastFrameId == 3);
  controller.render(segment);
  assert(segment.pixels[0] == 0x00FF00);
  // Stage an old-session frame, restart master with the same generation, and reject that DMA slot.
  publish(left, NodeRole::CameraLeft, 0xF800, 4);
  poll(10646);
  assert(controller.applyConfig(config));
  poll(10662);
  assert(controller.cameraStatus(wled::CameraSide::Left).framesReceived == 0);
  poll(10678);
  publish(left, NodeRole::CameraLeft, 0xFFFF, 5);
  poll(10694); poll(10710); poll(10726); poll(10742);
  assert(controller.cameraStatus(wled::CameraSide::Left).lastFrameId == 5);
  // A real camera reboot resets IDs while leaving the other camera's link independent.
  left.end(); assert(left.begin());
  poll(10758);
  publish(left, NodeRole::CameraLeft, 0x001F, 1);
  poll(10774); poll(10790); poll(10806); poll(10822);
  assert(controller.cameraStatus(wled::CameraSide::Left).lastFrameId == 1);
  config.generation++;
  config.topLeds = 7;
  assert(controller.applyConfig(config));
  poll(10838); poll(10854);
  assert(left.captureRequest(&request) && request.config.generation == 8 && request.config.top == 7);
  publish(left, NodeRole::CameraLeft, 0xF800, 2);
  poll(10870); poll(10886); poll(10902);
  assert(controller.cameraStatus(wled::CameraSide::Left).lastFrameId == 2);
  cinemaTest::exchange = {};
  controller._spiMaster.end(); left.end(); right.end();
  assert(cinemaTest::liveAllocations == 0);
}

int main() {
  testSampling();
  testCaptureContract();
  testEndToEnd();
  std::cout << "Cinema RGB checks passed: sampling, configuration, capture provenance, full-duplex frames and recovery.\n";
}
